/bin/zsh -lc "python3 -c 'from heapq import heappush, heappop

def distances(edges, source, bidirectional):
    graph = [[] for _ in range(4)]
    for u, v, w in edges:
        graph[u].append((v, w))
        if bidirectional:
            graph[v].append((u, w))
    dist = [float(\"inf\")] * 4
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        cost, u = heappop(heap)
        if cost "'!= dist[u]:
            continue
        for v, w in graph[u]:
            if cost + w < dist[v]:
                dist[v] = cost + w
                heappush(heap, (dist[v], v))
    return dist

cases = {
    "formal_sample": [(1, 2, 1), (2, 3, 1), (3, 1, 1)],
    "ambiguity_witness": [(1, 2, 10), (2, 3, 1), (3, 1, 1)],
}
for name, edges in cases.items():
    for bidirectional in (False, True):
        connected = all(all(value < float("inf") for value in distances(edges, s, bidirectional)[1:]) for s in range(1, 4))
        print(name, "bidirectional" if bidirectional else "u_to_v", "strongly_connected=", connected, "shortest_1_to_2=", distances(edges, 1, bidirectional)[2])
'"'"

